implementation:
#include <stdlib.h>
#include <string.h>

#include "magick.h"

size_t RegisterJPEGImage(void) {
  static const MagickInfo jpeg_info = {
    .name = "JPEG",
    .decoder = JPEGDecoder,
    .encoder = JPEGEncoder,
    .thread_support = MagickTrue,
    .mime_type = "image/jpeg",
  };

  static const MagickInfo jpeg_variants[] = {
    { .name = "JPE", .decoder = JPEGDecoder, .encoder = JPEGEncoder, .thread_support = MagickTrue, .mime_type = "image/jpeg" },
    { .name = "JPEG", .decoder = JPEGDecoder, .encoder = JPEGEncoder, .thread_support = MagickTrue, .mime_type = "image/jpeg" },
    { .name = "JPG", .decoder = JPEGDecoder, .encoder = JPEGEncoder, .thread_support = MagickTrue, .mime_type = "image/jpeg" },
    { .name = "JPS", .decoder = JPEGDecoder, .encoder = JPEGEncoder, .thread_support = MagickTrue, .mime_type = "image/jpeg" },
    { .name = "PJPEG", .decoder = JPEGDecoder, .encoder = JPEGEncoder, .thread_support = MagickTrue, .mime_type = "image/jpeg" },
  };

  static const char *jpeg_version = NULL;

  if (!jpeg_version) {
    jpeg_version = GetJPEGVersion();
  }

  size_t count = 0;

  MagickInfo *entry = CloneMagickInfo(&jpeg_info);
  if (entry) {
    entry->version = (char *)malloc(strlen(jpeg_version) + 1);
    if (entry->version) {
      strcpy(entry->version, jpeg_version);
    }
    count++;
    RegisterMagickInfo(entry);
  }

  for (size_t i = 0; i < sizeof(jpeg_variants) / sizeof(jpeg_variants[0]); i++) {
    MagickInfo *variant = CloneMagickInfo(&jpeg_variants[i]);
    if (variant) {
      variant->version = (char *)malloc(strlen(jpeg_version) + 1);
      if (variant->version) {
        strcpy(variant->version, jpeg_version);
      }
      count++;
      RegisterMagickInfo(variant);
    }
  }

  return count;
}
